export type IconName = keyof typeof NAMES;

export const ICON_NAMES = Object.keys(NAMES) as IconName[];

/** The drawing of OUI a name draws, and its shapes; nothing for a name the set does not have */
export function iconDrawing(name: string): { drawn: Drawn; viewBox: string; paths: readonly Shape[] } | undefined {
  if (!Object.prototype.hasOwnProperty.call(NAMES, name)) return undefined;
  const drawn: Drawn = NAMES[name as IconName];
  const drawing: Drawing = DRAWINGS[drawn];
  return { drawn, viewBox: drawing.viewBox ?? '0 0 16 16', paths: drawing.paths };
}

/** OUI's sizes: 12, 16, 24, 32 and 40 pixels */
export type IconSize = 's' | 'm' | 'l' | 'xl' | 'xxl';

export interface IconProps {
  name: IconName;
  size?: IconSize;
  className?: string;
  title?: string;
  /** An application's icon in its two colours, as the original draws one it gives no colour */
  app?: boolean;
}

export function Icon({ name, size = 'm', className, title, app }: IconProps) {
  const drawing = iconDrawing(name);
  const classes = ['atlIcon'];
  if (size !== 'm') classes.push(`atlIcon--${size}`);
  if (app) classes.push('atlIcon--app');
  if (className) classes.push(className);
  return (
    <svg
      className={classes.join(' ')}
      viewBox={drawing?.viewBox ?? '0 0 16 16'}
      xmlns="http://www.w3.org/2000/svg"
      focusable="false"
      role="img"
      aria-hidden={title ? undefined : true}
      aria-label={title}
    >
      {drawing?.paths.map((shape, index) =>
        typeof shape === 'string' ? (
          <path key={index} d={shape} />
        ) : (
          <path
            key={index}
            d={shape.d}
            fillRule={shape.evenOdd ? 'evenodd' : undefined}
            className={shape.secondary ? 'atlIcon__secondary' : undefined}
          />
        )
      )}
    </svg>
  );
}
